## 3. Result-Generation Logic (form data → recommendation)

Source: `client/src/lib/pediatricMentalHealthLogic.ts`

```typescript
/**
 * Pediatric Mental Health Screening Clinical Compass™
 * Logic Engine — AAP Mental Health Policy 2023/2025
 *
 * References:
 * 1. AAP. Addressing Mental Health Concerns in Pediatric Practice. Pediatrics. 2023.
 * 2. USPSTF. Screening for Anxiety in Children and Adolescents. JAMA. 2023.
 * 3. USPSTF. Screening for Depression and Suicide Risk in Children and Adolescents. JAMA. 2022.
 * 4. AAP. Suicide Prevention: Means Restriction Counseling. Pediatrics. 2024.
 * 5. AAP. ADHD Clinical Practice Guideline. Pediatrics. 2019 (updated 2023).
 * 6. AAP. Autism Spectrum Disorder Surveillance. Pediatrics. 2020 (updated 2024).
 */

export type MentalHealthAgeGroup =
  | "toddler_1_3"       // 1–3 years
  | "preschool_3_5"     // 3–5 years
  | "school_age_6_11"   // 6–11 years
  | "early_adolescent_12_14"
  | "adolescent_15_17"
  | "late_adolescent_18_21";

export interface PediatricMentalHealthInput {
  ageGroup: MentalHealthAgeGroup;
  ageYears: number;
  sex: "male" | "female" | "other";
  // Screening scores
  phq2Score: number | null;
  phq9Score: number | null;
  phq9ItemNineScore: number | null; // suicidal ideation item
  gad7Score: number | null;
  scaredScore: number | null; // SCARED (anxiety, ≥8 years)
  mchatScore: number | null; // M-CHAT-R/F (18–30 months)
  asqScore: "normal" | "monitor" | "refer" | null;
  vanderbiltScore: "normal" | "possible_adhd" | "adhd" | null; // ADHD
  crafftScore: number | null; // substance use (≥11 years)
  // Clinical context
  hasPriorMentalHealthDiagnosis: boolean;
  priorDiagnoses: string[];
  currentMedications: string[];
  hasActiveSuicidalIdeation: boolean;
  hasSuicidePlan: boolean;
  hasSuicideAttemptHistory: boolean;
  hasFirearmInHome: boolean;
  hasMedicationsInHome: boolean; // means restriction
  hasTraumaHistory: boolean; // ACEs, abuse, neglect
  hasChronicMedicalCondition: boolean;
  hasLGBTQIdentity: boolean; // higher mental health risk
  hasFamilyHistoryMentalIllness: boolean;
  hasFamilyHistorySuicide: boolean;
  hasSchoolProblems: boolean;
  hasSocialIsolation: boolean;
  hasBullyingExposure: boolean;
  hasSleepProblems: boolean;
  screenTimeHoursPerDay: number;
  physicalActivityMinutesPerDay: number;
  familySupportLevel: "strong" | "moderate" | "weak";
}

export interface MentalHealthScreeningResult {
  tool: string;
  score: string;
  interpretation: string;
  action: string;
}

export interface PediatricMentalHealthRecommendation {
  primaryRecommendation: string;
  screeningResults: MentalHealthScreeningResult[];
  urgentFlags: string[];
  diagnoses: string[];
  treatmentRecommendations: string[];
  referrals: string[];
  meansRestrictionCounseling: string;
  anticipatoryGuidance: string[];
  followUpPlan: string;
  evidenceLevel: "A" | "B" | "C";
  rationale: string;
  references: Array<{ citation: string; url: string }>;
}

export function assessPediatricMentalHealth(
  input: PediatricMentalHealthInput
): PediatricMentalHealthRecommendation {
  const urgentFlags: string[] = [];
  const screeningResults: MentalHealthScreeningResult[] = [];
  const diagnoses: string[] = [];
  const treatments: string[] = [];
  const referrals: string[] = [];
  const guidance: string[] = [];

  // ─── URGENT: Suicidal ideation ────────────────────────────────────────────
  if (input.hasActiveSuicidalIdeation || (input.phq9ItemNineScore !== null && input.phq9ItemNineScore >= 1)) {
    urgentFlags.push("ACTIVE SUICIDAL IDEATION: Conduct Columbia Suicide Severity Rating Scale (C-SSRS). Do NOT leave patient alone. Assess plan, intent, means access. If active plan or intent: EMERGENCY PSYCHIATRIC EVALUATION.");
    if (input.hasSuicidePlan) {
      urgentFlags.push("SUICIDE PLAN PRESENT: EMERGENCY — call 988 or 911. Psychiatric emergency evaluation. Do not discharge without safety plan and means restriction.");
    }
  }

  if (input.hasSuicideAttemptHistory) {
    urgentFlags.push("PRIOR SUICIDE ATTEMPT: High-risk for future attempt. Refer to mental health. Means restriction counseling mandatory. Safety plan required.");
    referrals.push("Mental health referral (priority) — prior suicide attempt is the strongest predictor of future attempt.");
  }

  // ─── Means restriction counseling ────────────────────────────────────────
  let meansRestriction: string;
  if (input.hasActiveSuicidalIdeation || input.hasSuicideAttemptHistory || (input.phq9Score !== null && input.phq9Score >= 10)) {
    meansRestriction = "MEANS RESTRICTION COUNSELING REQUIRED (AAP 2024): ";
    if (input.hasFirearmInHome) {
      meansRestriction += "FIREARM IN HOME: Counsel on safe storage (trigger lock, gun safe, separate storage of ammunition). Ideally remove firearms from home during mental health crisis. Lethal means counseling reduces suicide risk. ";
      urgentFlags.push("FIREARM IN HOME + MENTAL HEALTH RISK: Means restriction counseling mandatory. Recommend removing firearm from home during crisis.");
    }
    if (input.hasMedicationsInHome) {
      meansRestriction += "MEDICATIONS IN HOME: Lock medications. Dispense in small quantities. Consider blister packs. Remove excess medications.";
    }
  } else {
    meansRestriction = "Universal means restriction counseling at all well-child visits (AAP 2024): Ask about firearms in home. Counsel on safe storage regardless of mental health status.";
    if (input.hasFirearmInHome) {
      meansRestriction += " FIREARM PRESENT: Counsel on safe storage — trigger locks, gun safe, separate ammunition storage.";
    }
  }

  // ─── Depression screening (PHQ-2/PHQ-9) ──────────────────────────────────
  if (input.phq2Score !== null) {
    const phq2Interp = input.phq2Score >= 2 ? "POSITIVE — administer PHQ-9" : "Negative";
    screeningResults.push({ tool: "PHQ-2", score: `${input.phq2Score}`, interpretation: phq2Interp, action: input.phq2Score >= 2 ? "Administer PHQ-9. Assess for suicidal ideation." : "Continue annual screening." });
  }

  if (input.phq9Score !== null) {
    let phq9Interp: string;
    let phq9Action: string;
    if (input.phq9Score >= 20) {
      phq9Interp = "SEVERE depression";
      phq9Action = "URGENT psychiatric referral. Assess for hospitalization. Safety plan. Antidepressant + therapy.";
      urgentFlags.push(`PHQ-9 SEVERE (${input.phq9Score}): Urgent psychiatric evaluation. Assess for hospitalization.`);
      diagnoses.push("Major Depressive Disorder — severe");
      treatments.push("SSRI (fluoxetine preferred, FDA-approved ≥8 years) + CBT. Urgent psychiatric referral.");
      referrals.push("URGENT psychiatric evaluation for severe depression (PHQ-9 ≥20).");
    } else if (input.phq9Score >= 15) {
      phq9Interp = "Moderately severe depression";
      phq9Action = "Refer to mental health. Consider SSRI + CBT. Follow up in 2–4 weeks.";
      diagnoses.push("Major Depressive Disorder — moderately severe");
      treatments.push("SSRI (fluoxetine 10mg → 20mg, FDA-approved ≥8 years) + CBT. Refer to mental health.");
      referrals.push("Mental health referral for moderately severe depression (PHQ-9 ≥15).");
    } else if (input.phq9Score >= 10) {
      phq9Interp = "Moderate depression";
      phq9Action = "Refer to mental health. Consider SSRI. Follow up in 4 weeks.";
      diagnoses.push("Major Depressive Disorder — moderate");
      treatments.push("CBT first-line. SSRI if CBT not available or insufficient response. Follow up 4 weeks.");
      referrals.push("Mental health referral for moderate depression (PHQ-9 ≥10).");
    } else if (input.phq9Score >= 5) {
      phq9Interp = "Mild depression";
      phq9Action = "Watchful waiting. Supportive counseling. Follow up in 4–6 weeks. Rescreen.";
      treatments.push("Watchful waiting. Supportive counseling. Exercise, sleep hygiene, social support. Rescreen in 4–6 weeks.");
    } else {
      phq9Interp = "Minimal/no depression";
      phq9Action = "Continue annual screening.";
    }
    screeningResults.push({ tool: "PHQ-9", score: `${input.phq9Score}`, interpretation: phq9Interp, action: phq9Action });
  }

  // ─── Anxiety screening (GAD-7 / SCARED) ──────────────────────────────────
  if (input.gad7Score !== null) {
    let gad7Interp: string;
    let gad7Action: string;
    if (input.gad7Score >= 15) {
      gad7Interp = "Severe anxiety";
      gad7Action = "Refer to mental health. CBT + SSRI. Urgent if functional impairment severe.";
      diagnoses.push("Generalized Anxiety Disorder — severe");
      treatments.push("CBT (first-line) + SSRI (fluoxetine or sertraline). Refer to mental health.");
      referrals.push("Mental health referral for severe anxiety (GAD-7 ≥15).");
    } else if (input.gad7Score >= 10) {
      gad7Interp = "Moderate anxiety";
      gad7Action = "CBT referral. Consider SSRI if CBT not available.";
      diagnoses.push("Generalized Anxiety Disorder — moderate");
      treatments.push("CBT first-line. SSRI if CBT insufficient. Follow up 4–6 weeks.");
      referrals.push("Mental health referral for moderate anxiety (GAD-7 ≥10).");
    } else if (input.gad7Score >= 5) {
      gad7Interp = "Mild anxiety";
      gad7Action = "Psychoeducation. Relaxation techniques. Follow up in 4–6 weeks.";
    } else {
      gad7Interp = "Minimal anxiety";
      gad7Action = "Continue annual screening.";
    }
    screeningResults.push({ tool: "GAD-7", score: `${input.gad7Score}`, interpretation: gad7Interp, action: gad7Action });
  }

  // ─── ADHD screening (Vanderbilt) ─────────────────────────────────────────
  if (input.vanderbiltScore !== null && input.vanderbiltScore !== "normal") {
    const adhdAction = input.vanderbiltScore === "adhd"
      ? "ADHD confirmed: Behavior therapy (first-line ≤5 years). Medication ≥6 years: methylphenidate or amphetamine salts. Refer to developmental pediatrics or child psychiatry if complex."
      : "Possible ADHD: Obtain parent AND teacher Vanderbilt. Full evaluation per AAP 2023 ADHD CPG.";
    screeningResults.push({ tool: "Vanderbilt ADHD Rating Scale", score: input.vanderbiltScore, interpretation: input.vanderbiltScore === "adhd" ? "ADHD criteria met" : "Possible ADHD — further evaluation needed", action: adhdAction });
    if (input.vanderbiltScore === "adhd") {
      diagnoses.push("ADHD — confirmed by Vanderbilt");
      treatments.push("ADHD: Behavior therapy (first-line ≤5 years). Stimulant medication ≥6 years (methylphenidate or amphetamine). Classroom accommodations (504 plan or IEP). Recheck every 6 months.");
    }
  }

  // ─── Autism screening (M-CHAT) ────────────────────────────────────────────
  if (input.mchatScore !== null) {
    const mchatRisk = input.mchatScore >= 3 ? "high" : input.mchatScore >= 2 ? "medium" : "low";
    screeningResults.push({ tool: "M-CHAT-R/F", score: `${input.mchatScore}`, interpretation: `${mchatRisk.toUpperCase()} risk for autism`, action: mchatRisk === "high" ? "REFER to autism specialist + early intervention immediately" : mchatRisk === "medium" ? "Administer follow-up interview. Refer if still positive." : "Continue developmental surveillance." });
    if (mchatRisk === "high") {
      urgentFlags.push(`M-CHAT HIGH RISK (score ${input.mchatScore}): Refer for comprehensive autism evaluation + early intervention immediately. Do not wait for diagnosis.`);
      referrals.push("Autism evaluation: developmental pediatrics, child psychiatry, or neurology. Simultaneous early intervention referral.");
    }
  }

  // ─── Substance use (CRAFFT) ───────────────────────────────────────────────
  if (input.crafftScore !== null && input.crafftScore >= 2) {
    screeningResults.push({ tool: "CRAFFT", score: `${input.crafftScore}`, interpretation: "POSITIVE — substance use concern", action: "Brief intervention (BI). Refer to adolescent substance use treatment if CRAFFT ≥2." });
    urgentFlags.push(`CRAFFT POSITIVE (score ${input.crafftScore}): Brief intervention. Refer to adolescent substance use treatment.`);
    referrals.push("Adolescent substance use treatment referral (CRAFFT ≥2).");
  }

  // ─── Risk factors ─────────────────────────────────────────────────────────
  if (input.hasTraumaHistory) {
    treatments.push("Trauma history (ACEs): Trauma-focused CBT (TF-CBT). Refer to trauma-informed mental health provider. Screen for PTSD (Child PTSD Symptom Scale).");
    referrals.push("Trauma-informed mental health referral for ACEs/trauma history.");
  }
  if (input.hasLGBTQIdentity) {
    guidance.push("LGBTQ+ youth: 4× higher risk of depression, anxiety, and suicide. Affirming care. Refer to LGBTQ+-affirming mental health provider. Discuss safe spaces and support resources (Trevor Project: 1-866-488-7386).");
    if (!referrals.some(r => r.includes("mental health"))) {
      referrals.push("LGBTQ+-affirming mental health provider referral.");
    }
  }
  if (input.hasBullyingExposure) {
    guidance.push("Bullying exposure (in-person or cyberbullying): Screen for depression and anxiety. Involve school counselor. Provide resources for reporting bullying.");
  }
  if (input.screenTimeHoursPerDay > 3) {
    guidance.push(`Excessive screen time (${input.screenTimeHoursPerDay} hours/day): Limit recreational screen time to ≤2 hours/day for school-age children. No screens 1 hour before bedtime. Discuss social media mental health effects.`);
  }
  if (input.physicalActivityMinutesPerDay < 60) {
    guidance.push(`Insufficient physical activity (${input.physicalActivityMinutesPerDay} min/day): Recommend 60 min/day MVPA. Physical activity reduces depression and anxiety symptoms.`);
  }
  if (input.hasSleepProblems) {
    guidance.push("Sleep problems: Sleep hygiene counseling (consistent bedtime, no screens 1 hour before bed, cool dark room). Adequate sleep: 9–12 hours (6–12 years), 8–10 hours (13–18 years). Melatonin 0.5–1mg for sleep onset if needed.");
  }

  // ─── Follow-up ────────────────────────────────────────────────────────────
  const followUp = urgentFlags.length > 0
    ? "URGENT follow-up within 1–2 weeks or sooner if safety concern. Provide crisis resources: 988 Suicide & Crisis Lifeline, Crisis Text Line (text HOME to 741741)."
    : diagnoses.length > 0
    ? "Follow up in 4–6 weeks to assess treatment response. Rescreen with validated tools at follow-up."
    : "Annual mental health screening at well-child visits. Follow up as needed.";

  const primaryRec = urgentFlags.length > 0
    ? urgentFlags[0]
    : diagnoses.length > 0
    ? `MENTAL HEALTH CONCERN IDENTIFIED: ${diagnoses.join(", ")}. ${treatments[0] ?? "Refer to mental health."}`
    : `PEDIATRIC MENTAL HEALTH SCREENING — ${input.ageGroup.replace(/_/g, " ")}. No acute concerns identified. Continue annual screening per AAP 2025 guidelines.`;

  return {
    primaryRecommendation: primaryRec,
    screeningResults,
    urgentFlags,
    diagnoses,
    treatmentRecommendations: treatments,
    referrals,
    meansRestrictionCounseling: meansRestriction,
    anticipatoryGuidance: guidance,
    followUpPlan: followUp,
    evidenceLevel: "A",
    rationale: `Age group: ${input.ageGroup}. PHQ-9: ${input.phq9Score ?? "not obtained"}. GAD-7: ${input.gad7Score ?? "not obtained"}. Active SI: ${input.hasActiveSuicidalIdeation}. Prior attempt: ${input.hasSuicideAttemptHistory}. Firearm in home: ${input.hasFirearmInHome}. Per AAP 2023/2025 mental health policy.`,
    references: [
      { citation: "AAP. Addressing Mental Health Concerns in Pediatric Practice. Pediatrics. 2023.", url: "https://publications.aap.org/pediatrics" },
      { citation: "USPSTF. Screening for Anxiety in Children and Adolescents. JAMA. 2023;329(24):2163–2173.", url: "https://jamanetwork.com/journals/jama/fullarticle/2806326" },
      { citation: "USPSTF. Screening for Depression and Suicide Risk in Children and Adolescents. JAMA. 2022;328(15):1534–1542.", url: "https://jamanetwork.com/journals/jama/fullarticle/2797177" },
      { citation: "AAP. Suicide Prevention: Means Restriction Counseling. Pediatrics. 2024.", url: "https://publications.aap.org/pediatrics" },
      { citation: "AAP. ADHD Clinical Practice Guideline. Pediatrics. 2019 (updated 2023).", url: "https://publications.aap.org/pediatrics/article/144/4/e20192528" },
    ],
  };
}
